"use client";

import { useRef } from "react";
import { motion, useReducedMotion } from "motion/react";
import { LiquidGlass } from "@/components/ui/liquid-glass";

type LiquidGlassDemoProps = {
  shape?: "circle" | "pill";
  scale?: number;
  aberration?: number;
  bevelDepth?: number;
  frost?: number;
  tint?: number;
};

export function LiquidGlassDemo({
  shape = "circle",
  scale = 48,
  aberration = 14,
  bevelDepth = 37,
  frost = 0.4,
  tint = 0.12,
}: LiquidGlassDemoProps) {
  const constraintsRef = useRef<HTMLDivElement>(null);
  const reduceMotion = useReducedMotion();
  const size = shape === "pill" ? { w: 320, h: 120 } : { w: 200, h: 200 };

  return (
    <div
      ref={constraintsRef}
      className="relative h-[36rem] w-full overflow-hidden bg-neutral-900"
    >
      <img
        src="https://assets.aceternity.com/screenshots/colourful-office.webp"
        alt=""
        className="absolute inset-0 size-full object-cover"
        draggable={false}
      />
      <div className="pointer-events-none absolute inset-0 flex flex-col items-center justify-center p-8 text-center select-none">
        <p className="text-6xl leading-[0.95] font-bold tracking-tighter text-white md:text-8xl">
          Bend the
          <br />
          light.
        </p>
        <div className="mt-8 grid w-full max-w-md grid-cols-12 gap-1.5">
          {Array.from({ length: 48 }).map((_, i) => (
            <span key={i} className="h-1.5 rounded-full bg-white/80" />
          ))}
        </div>
      </div>

      <motion.div
        drag
        dragConstraints={constraintsRef}
        dragElastic={0.1}
        whileDrag={reduceMotion ? undefined : { scale: 1.04 }}
        className="absolute top-1/2 left-1/2 cursor-grab touch-none active:cursor-grabbing"
        style={{
          width: size.w,
          height: size.h,
          marginLeft: -size.w / 2,
          marginTop: -size.h / 2,
        }}
      >
        <LiquidGlass
          radius={size.h / 2}
          scale={scale}
          aberration={aberration}
          bevelDepth={bevelDepth}
          frost={frost}
          tint={tint}
          className="size-full shadow-[0_12px_40px_rgb(0_0_0/0.25),inset_0_1px_0_rgb(255_255_255/0.5)]"
        />
      </motion.div>
    </div>
  );
}

"use client";

import { useState } from "react";
import { motion, useReducedMotion } from "motion/react";
import {
  IconBell,
  IconHeart,
  IconHome,
  IconSearch,
  IconUser,
} from "@tabler/icons-react";
import { cn } from "@/lib/utils";
import { LiquidGlass } from "@/components/ui/liquid-glass";

const FEED = [
  { image: "components/hero-1.webp", title: "Hero sections", meta: "24 variants" },
  { image: "components/3d-globe.webp", title: "3D Globe", meta: "WebGL" },
  {
    image: "components/hero-section-with-mesh-gradient.webp",
    title: "Mesh gradients",
    meta: "Shaders",
  },
  { image: "components/keyboard-2.webp", title: "Keyboard", meta: "Interactive" },
  { image: "components/hero-2.webp", title: "Product heroes", meta: "12 variants" },
  { image: "components/hero-3.webp", title: "SaaS heroes", meta: "8 variants" },
];

const TABS = [
  { label: "Home", icon: IconHome },
  { label: "Search", icon: IconSearch },
  { label: "Alerts", icon: IconBell },
  { label: "Profile", icon: IconUser },
];

export function LiquidGlassAppChromeDemo() {
  const reduceMotion = useReducedMotion();
  const [active, setActive] = useState(0);

  return (
    <div className="flex w-full justify-center bg-neutral-100 py-10 dark:bg-neutral-900">
      <div className="relative h-[640px] w-[320px] overflow-hidden rounded-[48px] border-[6px] border-neutral-900 bg-white shadow-2xl dark:border-neutral-700">
        <div className="h-full overflow-y-auto px-3 pt-24 pb-28 [scrollbar-width:none]">
          <div className="flex flex-col gap-3">
            {FEED.map((item) => (
              <article
                key={item.title}
                className="overflow-hidden rounded-3xl bg-neutral-100"
              >
                <img
                  src={`https://assets.aceternity.com/${item.image}`}
                  alt=""
                  className="aspect-[4/3] w-full object-cover"
                />
                <div className="flex items-center justify-between px-4 py-3">
                  <div>
                    <h3 className="text-sm font-semibold text-neutral-900">
                      {item.title}
                    </h3>
                    <p className="text-xs text-neutral-500">{item.meta}</p>
                  </div>
                  <IconHeart className="size-5 text-neutral-400" />
                </div>
              </article>
            ))}
          </div>
        </div>

        <LiquidGlass
          radius={28}
          bevelDepth={12}
          scale={36}
          tint={0.35}
          className="absolute inset-x-3 top-3 shadow-[0_4px_20px_rgb(0_0_0/0.08),inset_0_1px_0_rgb(255_255_255/0.6)]"
          contentClassName="flex h-14 items-center justify-between px-5"
        >
          <span className="text-lg font-semibold tracking-tight text-neutral-900">
            Discover
          </span>
          <img
            src="https://assets.aceternity.com/avatars/manu.webp"
            alt=""
            className="size-8 rounded-full object-cover"
          />
        </LiquidGlass>

        <LiquidGlass
          bevelDepth={10}
          scale={28}
          aberration={2}
          tint={0.55}
          className="absolute inset-x-0 bottom-4 mx-auto w-fit shadow-[0_6px_20px_rgb(0_0_0/0.10),0_0_0_1px_rgb(0_0_0/0.04),inset_0_1px_0_rgb(255_255_255/0.8)]"
          contentClassName="flex p-1"
        >
          {TABS.map((tab, i) => (
            <button
              key={tab.label}
              onClick={() => setActive(i)}
              aria-label={tab.label}
              aria-current={active === i ? "page" : undefined}
              className={cn(
                "relative flex h-11 w-14 flex-col items-center justify-center gap-0.5 rounded-full text-[9px] font-medium tracking-tight",
                active === i ? "text-neutral-900" : "text-neutral-500",
              )}
            >
              {active === i && (
                <motion.span
                  layoutId="liquid-glass-tab"
                  className="absolute inset-0 rounded-full bg-neutral-900/[0.06]"
                  transition={
                    reduceMotion
                      ? { duration: 0 }
                      : { type: "spring", bounce: 0.2, duration: 0.4 }
                  }
                />
              )}
              <tab.icon className="relative size-[18px]" stroke={1.75} />
              <span className="relative">{tab.label}</span>
            </button>
          ))}
        </LiquidGlass>
      </div>
    </div>
  );
}

"use client";

import { motion, useReducedMotion } from "motion/react";
import { IconArrowRight, IconRocket } from "@tabler/icons-react";
import { LiquidGlass } from "@/components/ui/liquid-glass";

const LINKS = ["Product", "Pricing", "Changelog", "Docs"];

const GLASS_SHADOW =
  "shadow-[0_10px_40px_rgb(0_0_0/0.18),inset_0_1px_0_rgb(255_255_255/0.45)]";

export function LiquidGlassHeroDemo() {
  const reduceMotion = useReducedMotion();
  const interaction = reduceMotion
    ? {}
    : { whileHover: { scale: 1.03 }, whileTap: { scale: 0.97 } };

  return (
    <section className="relative isolate flex min-h-[44rem] w-full flex-col overflow-hidden px-4 text-white">
      <img
        src="https://assets.aceternity.com/screenshots/13.jpg"
        alt=""
        className="absolute inset-0 -z-10 size-full object-cover object-[center_40%]"
      />
      <div className="absolute inset-0 -z-10 bg-gradient-to-b from-black/30 via-transparent to-black/40" />

      <LiquidGlass
        tint={0.1}
        scale={32}
        bevelDepth={12}
        className={`mx-auto mt-4 w-full max-w-4xl ${GLASS_SHADOW}`}
        contentClassName="flex items-center justify-between py-2 pr-2 pl-5"
      >
        <a href="#" className="flex items-center gap-2 font-semibold">
          <IconRocket className="size-5" stroke={1.75} />
          Orbit
        </a>
        <nav className="hidden items-center gap-7 text-sm text-white/80 md:flex">
          {LINKS.map((link) => (
            <a key={link} href="#" className="hover:text-white">
              {link}
            </a>
          ))}
        </nav>
        <div className="flex items-center gap-2">
          <a
            href="#"
            className="hidden px-3 text-sm text-white/80 hover:text-white sm:block"
          >
            Sign in
          </a>
          <motion.a
            {...interaction}
            href="#"
            className="rounded-full bg-white px-4 py-2 text-sm font-medium text-neutral-900"
          >
            Start free
          </motion.a>
        </div>
      </LiquidGlass>

      <div className="mx-auto flex max-w-3xl flex-1 flex-col items-center justify-center py-20 text-center">
        <a href="#" className="rounded-full">
          <LiquidGlass
            tint={0.12}
            scale={24}
            bevelDepth={10}
            aberration={2}
            className={GLASS_SHADOW}
            contentClassName="flex items-center gap-2 py-1.5 pr-3 pl-1.5 text-sm"
          >
            <span className="rounded-full bg-white px-2 py-0.5 text-xs font-medium text-neutral-900">
              New
            </span>
            <span className="text-white/90">Launch week is live</span>
            <IconArrowRight className="size-3.5 text-white/70" />
          </LiquidGlass>
        </a>

        <h1 className="mt-6 text-5xl font-semibold tracking-tight text-balance [text-shadow:0_2px_16px_rgb(0_0_0/0.25)] md:text-7xl">
          Ship your product into orbit.
        </h1>
        <p className="mt-5 max-w-xl text-lg text-pretty text-white/80 [text-shadow:0_1px_8px_rgb(0_0_0/0.3)]">
          Orbit plans, builds and launches your releases in one place, so your
          team spends less time on process and more time on the product.
        </p>

        <div className="mt-10 flex flex-wrap items-center justify-center gap-3">
          <motion.button {...interaction} className="rounded-full">
            <LiquidGlass
              tint={0.2}
              className={GLASS_SHADOW}
              contentClassName="flex items-center gap-2 px-7 py-3.5 font-medium [text-shadow:0_1px_2px_rgb(0_0_0/0.25)]"
            >
              Book a demo
              <IconArrowRight className="size-4" />
            </LiquidGlass>
          </motion.button>
          <motion.button
            {...interaction}
            className="rounded-full bg-white px-7 py-3.5 font-medium text-neutral-900 shadow-lg"
          >
            Start for free
          </motion.button>
        </div>

        <p className="mt-8 text-sm text-white/70">
          Free for teams up to 5. No credit card needed.
        </p>
      </div>
    </section>
  );
}
